import{_ as a,o,c as r,ab as t}from"./chunks/framework.DfnUYNhO.js";const h=JSON.parse('{"title":"共同操作とチームアクセスを準備する","description":"","frontmatter":{"title":"共同操作とチームアクセスを準備する","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"ja","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"05f448dda78b05027b84b2c03f08a15eb515aee05af79397a1596d7e40ec5d40","translationRevision":"8dc4eeba1d61d910188f76b01efa8e67d4e1e04a4def1b03952cf43823387e48","order":30},"headers":[],"relativePath":"ja/user/cloud/collaboration.md","filePath":"ja/user/cloud/collaboration.md","lastUpdated":1795474668000}'),l={name:"ja/user/cloud/collaboration.md"};function c(i,e,n,d,s,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">共同操作とチームアクセスを準備する <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;共同操作とチームアクセスを準備する {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>所有者の管理権を保ちながら、別のオペレーターに定義された役割を割り当てます。リモートアクセスは設定のタブではなく、インストール可能な <strong>Remote Control</strong> プラグインが提供します。<a href="./account.html">Cloud ログイン</a>、対応するバックエンド、およびこのホストへのプラグインのインストールが必要です。まずは読み取り専用アクセスと本番以外の環境から始めます。</p><h2 id="configure-remote-access" tabindex="-1">リモートアクセスを設定する <a class="header-anchor" href="#configure-remote-access" aria-label="Permalink to &quot;リモートアクセスを設定する {#configure-remote-access}&quot;">​</a></h2><ol><li><code>tiktools.remote-control</code> をインストールして有効にし、<strong>Remote control</strong> ページを開きます。</li><li>チームを作成し、<strong>この PC</strong> をホストとして登録して識別しやすいデバイス名を付けます。リレーリンクを開始し、ステータスが <code>ready</code> になるまで待ちます。</li><li>招待を作成し、一度だけ表示されるトークンを信頼できる経路で渡します。招待は承認済みのアクティブセッションではありません。</li><li>保留中のリクエストと要求された役割を確認します。期待するオペレーターだけを承認してください。付与はホストリンクが確認するまで <code>pendingHost</code> のままです。</li><li>付与とデバイスを定期的に確認します。不要になった付与は取り消します。</li></ol><p>委譲された定義の編集、所有者としての定義の採用、委譲された実行の承認は別々の判断です。保存されたソース、参照されるアクション、権限を対象のレビューで読みます。定義のプレビューだけでは副作用は許可されません。</p><h2 id="prepare-a-controller-device" tabindex="-1">コントローラーデバイスを準備する <a class="header-anchor" href="#prepare-a-controller-device" aria-label="Permalink to &quot;コントローラーデバイスを準備する {#prepare-a-controller-device}&quot;">​</a></h2><p>コントローラー側のデバイスで独自のアカウントにログインし、コントローラーとして登録して招待トークンを引き換えます。所有者に保留中のリクエストが表示されます。ニックネーム検索には別途デプロイされたバックエンドのエンドポイントが必要で、現在のサービスでは利用できない場合があります。検索の失敗をアカウント不在と判断したり、選択を任意の ID で置き換えたりしないでください。</p><h2 id="expected-result-and-status" tabindex="-1">期待する結果とステータス <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待する結果とステータス {#expected-result-and-status}&quot;">​</a></h2><p>2 アカウントのフロー（チーム、ホストリンク、招待、承認、読み取りコマンド、取り消し）はローカルバックエンドで検証済みです。設定の Collaboration/Teams タブは削除され、ネイティブの collaboration サービスにはこのビルドに Web UI がありません。本番のリレー/NAT 動作、ニックネーム検索、2 台の PC での LIVE 運用はここでは確認されていません。リンクの準備だけでは、目的の操作に対する権限の適用を保証しません。</p><h2 id="recovery" tabindex="-1">リカバリー <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;リカバリー {#recovery}&quot;">​</a></h2><p>古い付与の場合はアクセスを取り消し、ホストリンクの更新後に再確認します。未確認のコマンドは、再試行前に記録された結果を確認します。セッション終了時はリレーリンクを停止するかアクセスを取り消します。招待トークンや認証情報は公開の<a href="./../preferences/troubleshooting.html">診断レポート</a>に含めないでください。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>すべてのリモートコマンドはホストのケーパビリティゲート（<code>remote.command.dispatch</code>、<code>remote.pair.list</code>、<code>remote.grant.list</code>、<code>remote.grant.revoke</code>、<code>remote.controller.ticket</code>）を通過し、プラグインは Control API や完全な bearer トークンを受け取りません。アクティブなトランスポートやチームへの参加だけではネイティブアクセスは付与されません。Observer は読み取り指向、moderator は一部の操作を追加し、automationEditor は一部の編集を追加し、custom には明示的にレビューされたポリシーが必要です。いずれも無制限のスクリプトや副作用を許可しません。現在の境界については<a href="./../../developer/collaboration.html#operational-details">役割と確認の契約</a>と<a href="./../../developer/transports.html">トランスポート</a>を参照してください。</p>',14)])])}const m=a(l,[["render",c]]);export{h as __pageData,m as default};
